```rust
//! S #17 Imprisoned Ship Smith (SPEC §8.10 row 17): (1) Unit, Human, Common, 2/2 → 4/4, of the held
//! Stinkyscape set (R1420).
//!   Base:    "Dormant for 2 turns. When this awakens, summon a Fiery Waraxe."
//!   Radiant: "Dormant for 2 turns. When this awakens, summon a Radiant Fiery Waraxe."
//! Engine: Dormant (R1839000), `StaticFlags.slumber { turns: 2 }`, counted at the start of its
//! controller's turns and awake at the start of the second, before the start-of-turn triggers, not
//! summoning sick (R1839001). `when_this_awakens` (R1839002): a fresh M #66 Fiery Waraxe into the
//! leftmost open backrow zone (R64), no Cry (R1); a full backrow summons nothing. It enters on its
//! controller's turn, so it animates as it enters (§6.1 "Animated on your turn"): an entry, so
//! summoning sick (R1062), its Rush letting it attack a Unit that turn. Radiant: a Radiant Waraxe.

use jackioh_engine::prelude::*;

pub const ID: &str = "stinkyscape-017";

/// M #66 Fiery Waraxe, what the awakening summons.
const WARAXE: &str = "meditative-066";

/// "Dormant for 2 turns": the status's printed count, no param (docs/stinkyscape-set.md, #17).
const DORMANT_TURNS: i32 = 2;

fn ship_smith(radiant: bool) -> Script {
    Script {
        static_flags: Some(StaticFlags {
            slumber: Some(SlumberText {
                turns: Some(DORMANT_TURNS),
                wakes_by: None,
            }),
            ..StaticFlags::default()
        }),
        triggers: vec![when_this_awakens("awakens", move |_ctx, _event| {
            vec![summon(json_as(json!({ "defId": WARAXE, "radiant": radiant })))]
        })],
        ..Script::default()
    }
}

pub fn script() -> CardScripts {
    CardScripts {
        base: ship_smith(false),
        radiant: ship_smith(true),
    }
}

// S #17 Imprisoned Ship Smith — SPEC §8.10 row 17, BUILD M12 row S 17.
#[cfg(test)]
mod tests {
    use jackioh_engine::testkit::PlayerId::{P1, P2};
    use jackioh_engine::testkit::*;

    use super::{DORMANT_TURNS, ID, WARAXE};

    const FILLER: &str = "core-010"; // (0) Spell: a play always open, so no turn ends by itself.
    const VANILLA: &str = "core-008"; // (1) 4/4.
    const HIT_JOB: &str = "core-016"; // (3) Spell: Destroy a Unit.
    const RESERVES: &str = "core-075"; // (0) Field Spell that does nothing here: a backrow zone taken.
    const FARM: &str = "core-058"; // (2) Field Spell: Start of turn: Summon a Rush Token.
    const RUSH_TOKEN: &str = "core-t-rush";

    /// p1 has played the Smith (`radiant` its face) into unit zone 1, `p1_backrow` in its backrow; p2
    /// has a Vanilla in unit zone 1 and a Hit Job in hand.
    fn played(radiant: bool, p1_backrow: Value) -> Scenario {
        let mut s = crate::scenario(json!({
            "p1": {
                "hand": [{ "def": ID, "radiant": radiant }, FILLER],
                "backrow": p1_backrow,
                "library": crate::filler(4),
            },
            "p2": { "hand": [HIT_JOB, FILLER], "field": [VANILLA], "library": crate::filler(4) },
        }));
        s.play(ID, json!({ "zone": 1 }));
        s
    }

    /// Both players' next two turns: the start of p1's second turn after the play awakens it.
    fn to_its_awakening(s: &mut Scenario) {
        s.end_turn().end_turn().end_turn().end_turn();
        assert_eq!(s.state().active, P1);
    }

    fn dormant_for(turns: i32) -> Option<Slumber> {
        Some(Slumber { turns: Some(turns) })
    }

    /// Whether any legal action of `player` names `id`: an attack, a switch, a play's pick.
    fn named_by_a_legal_action(s: &Scenario, player: PlayerId, id: &str) -> bool {
        legal_actions(s.state(), player)
            .iter()
            .any(|action| serde_json::to_string(action).expect("serialises").contains(&format!("\"{id}\"")))
    }

    /// Where in `events` `matches` first holds.
    fn first(events: &[GameEvent], matches: impl Fn(&GameEvent) -> bool) -> Option<usize> {
        events.iter().position(matches)
    }

    fn awakened(event: &GameEvent) -> bool {
        matches!(event, GameEvent::Awakened { .. })
    }

    /// The row and lane of every Waraxe summoned so far.
    fn summoned_waraxes(s: &Scenario) -> Vec<(Row, i32)> {
        s.events()
            .iter()
            .filter_map(|event| match event {
                GameEvent::Summoned { def_id, row, lane, .. } if def_id == WARAXE => Some((*row, *lane)),
                _ => None,
            })
            .collect()
    }

    mod base {
        use super::*;

        #[test]
        fn r1839000_played_it_lies_dormant_for_2_turns_no_attack_no_switch_no_target() {
            let mut s = played(false, json!([]));
            let smith = s.card(ID).id.clone();
            assert_eq!(s.card(&smith).slumber, dormant_for(DORMANT_TURNS));
            assert!(!named_by_a_legal_action(&s, P1, &smith));
            s.expect_refused(|s| s.attack(&smith, "hero"));

            s.end_turn();
            // The opponent's turn: its Vanilla may not attack it, and its Hit Job may not name it.
            assert!(!named_by_a_legal_action(&s, P2, &smith));
            s.expect_refused(|s| s.attack(VANILLA, &smith));
        }

        #[test]
        fn r1839001_awakens_at_the_start_of_its_controllers_second_turn_before_the_turns_triggers_not_sick() {
            let mut s = played(false, json!([FARM]));
            let smith = s.card(ID).id.clone();
            s.end_turn().end_turn();
            assert_eq!(s.card(&smith).slumber, dormant_for(DORMANT_TURNS - 1));
            assert!(first(s.events(), awakened).is_none());

            s.end_turn().end_turn();
            assert_eq!(s.card(&smith).slumber, None);
            let woke = first(s.last_events(), awakened);
            let farm_token = first(
                s.last_events(),
                |event| matches!(event, GameEvent::Summoned { def_id, .. } if def_id == RUSH_TOKEN),
            );
            assert!(woke.is_some() && woke < farm_token);
            s.attack(&smith, "hero");
            s.expect_health(P2, HERO_HEALTH - 2);
        }

        #[test]
        fn r64_its_awakening_summons_a_fiery_waraxe_into_the_leftmost_open_backrow_zone_and_it_animates() {
            let mut s = played(false, json!([{ "def": RESERVES, "lane": 1 }]));
            to_its_awakening(&mut s);

            assert_eq!(summoned_waraxes(&s), vec![(Row::Backrow, 2)]);
            let woke = first(s.events(), awakened);
            let summoned = first(
                s.events(),
                |event| matches!(event, GameEvent::Summoned { def_id, .. } if def_id == WARAXE),
            );
            assert!(woke.is_some() && woke < summoned);
            // §6.1: on its controller's turn it animates as it enters, into its own lane's unit zone.
            let waraxe = s.unit_at(P1, 2);
            assert_eq!(waraxe.def_id, WARAXE);
            assert!(!waraxe.radiant);
            s.expect_stats(&waraxe, json!({ "attack": 3, "health": 2 }));
            // An entry, so sick (R1062): its Rush lets it hit a Unit, not the hero.
            s.expect_refused(|s| s.attack(&waraxe, "hero"));
            s.attack(&waraxe, VANILLA);
            s.expect_stats(VANILLA, json!({ "health": 1 }));
        }

        #[test]
        fn a_full_backrow_summons_no_waraxe() {
            let reserves: Vec<Value> = (1..=5).map(|lane| json!({ "def": RESERVES, "lane": lane })).collect();
            let mut s = played(false, json!(reserves));
            to_its_awakening(&mut s);

            assert!(first(s.events(), awakened).is_some());
            assert!(summoned_waraxes(&s).is_empty());
            assert!((1..=5).all(|lane| s.unit(P1, lane).is_none_or(|unit| unit.def_id != WARAXE)));
        }
    }

    mod radiant {
        use super::*;

        #[test]
        fn r275_a_4_4_whose_awakening_summons_a_radiant_fiery_waraxe_6_4_with_pierce() {
            let mut s = played(true, json!([]));
            s.expect_stats(ID, json!({ "attack": 4, "health": 4 }));
            to_its_awakening(&mut s);

            assert_eq!(summoned_waraxes(&s), vec![(Row::Backrow, 1)]);
            let waraxe = s.unit_at(P1, 2);
            assert!(waraxe.radiant);
            s.expect_stats(&waraxe, json!({ "attack": 6, "health": 4 }));
            assert!(has_keyword(&s.stats(&waraxe).keywords, KeywordKind::Pierce));
        }
    }
}
```

**File B**: `c019_imprisoned_cosmality.rs`

```rust
//! S #19 Imprisoned Cosmality (SPEC §8.10 row 19): (2) Unit, Common, 10/6 → 20/12, of the held
//! Stinkyscape set (R1420).
//!   Base:    "Pierce / Dormant for 2 turns. When this awakens, deal {damage} damage randomly split
//!            among all enemies." ({damage} 10)
//!   Radiant: the same text, {damage} 20.
//! Engine: Pierce (R346) is catalog data. Dormant (R1839000), `StaticFlags.slumber { turns: 2 }`,
//! awake at the start of its controller's second turn after it arrived, not summoning sick
//! (R1839001). `when_this_awakens` (R1839002): C+ #3's `damage_split`, {damage} hits of 1, each on an
//! enemy drawn from the match rng among the enemy hero and the enemy Units still standing (R60), with
//! no state check between the hits (R59); each hit's source is this Unit, so each pierces Armor
//! (R346). Both faces run this script; the number is the face's declared `damage` (R386).

use jackioh_engine::prelude::*;

pub const ID: &str = "stinkyscape-019";

/// "Dormant for 2 turns": the status's printed count, no param (docs/stinkyscape-set.md, #19).
const DORMANT_TURNS: i32 = 2;

pub fn script() -> CardScripts {
    let base = Script {
        static_flags: Some(StaticFlags {
            slumber: Some(SlumberText {
                turns: Some(DORMANT_TURNS),
                wakes_by: None,
            }),
            ..StaticFlags::default()
        }),
        triggers: vec![when_this_awakens("awakens", |ctx, _event| {
            let damage = param(&*ctx, "damage");
            vec![damage_split(json_as(json!({ "amount": damage, "among": "enemies" })))]
        })],
        ..Script::default()
    };
    // The Radiant face differs only in its stats and its `damage` value (20), both catalog data.
    let radiant = base.clone();
    CardScripts { base, radiant }
}

// S #19 Imprisoned Cosmality — SPEC §8.10 row 19, BUILD M12 row S 19.
#[cfg(test)]
mod tests {
    use jackioh_engine::testkit::PlayerId::{P1, P2};
    use jackioh_engine::testkit::*;

    use super::{DORMANT_TURNS, ID};
    use crate::merged;

    const FILLER: &str = "core-010"; // (0) Spell: a play always open, so no turn ends by itself.
    const VANILLA: &str = "core-008"; // (1) 4/4.
    const MR_TOKEN: &str = "core-015"; // (1) 1/1.
    const ENEMY_HERO: &str = "hero-p2";

    /// p1 has played the Cosmality (`radiant` its face) into unit zone 1; p2's side is `p2` over a
    /// hand and a library; `seed` is the match's.
    fn played(radiant: bool, p2: Value, seed: &str) -> Scenario {
        let mut s = crate::scenario(json!({
            "seed": seed,
            "p1": { "hand": [{ "def": ID, "radiant": radiant }, FILLER], "library": crate::filler(4) },
            "p2": merged(json!({ "hand": [FILLER], "library": crate::filler(4) }), p2),
        }));
        s.play(ID, json!({ "zone": 1 }));
        s
    }

    /// Both players' next two turns: the start of p1's second turn after the play awakens it.
    fn to_its_awakening(s: &mut Scenario) {
        s.end_turn().end_turn().end_turn().end_turn();
        assert_eq!(s.state().active, P1);
    }

    fn dormant_for(turns: i32) -> Option<Slumber> {
        Some(Slumber { turns: Some(turns) })
    }

    /// One of the Cosmality's `damage` events: where it sits in the event list, what it hit, how hard.
    struct Hit {
        index: usize,
        target_id: String,
        amount: i32,
    }

    fn hits(s: &Scenario) -> Vec<Hit> {
        let id = s.card(ID).id.clone();
        s.events()
            .iter()
            .enumerate()
            .filter_map(|(index, event)| match event {
                GameEvent::Damage { source_id: Some(source), target_id, amount, .. } if *source == id => {
                    Some(Hit { index, target_id: target_id.clone(), amount: *amount })
                }
                _ => None,
            })
            .collect()
    }

    mod base {
        use super::*;

        #[test]
        fn r1839001_played_it_lies_dormant_and_awakens_at_the_start_of_its_controllers_second_turn_after() {
            let mut s = played(false, json!({}), "cosmality");
            let cosmality = s.card(ID).id.clone();
            assert_eq!(s.card(&cosmality).slumber, dormant_for(DORMANT_TURNS));
            s.expect_refused(|s| s.attack(&cosmality, "hero"));

            s.end_turn().end_turn();
            assert_eq!(s.card(&cosmality).slumber, dormant_for(DORMANT_TURNS - 1));
            assert!(hits(&s).is_empty());

            s.end_turn().end_turn();
            assert_eq!(s.card(&cosmality).slumber, None);
            assert!(s.last_events().iter().any(|event| matches!(event, GameEvent::Awakened { .. })));
        }

        #[test]
        fn r60_when_it_awakens_10_hits_of_1_each_on_the_enemy_hero_or_an_enemy_unit() {
            let mut s = played(false, json!({ "field": [VANILLA, VANILLA] }), "cosmality");
            let vanillas: Vec<String> = [1, 2].iter().map(|&lane| s.unit_at(P2, lane).id).collect();
            to_its_awakening(&mut s);

            let hits = hits(&s);
            assert_eq!(hits.len(), 10);
            assert!(hits.iter().all(|hit| hit.amount == 1));
            assert!(hits.iter().all(|hit| hit.target_id == ENEMY_HERO || vanillas.contains(&hit.target_id)));
            let on_hero = hits.iter().filter(|hit| hit.target_id == ENEMY_HERO).count() as i32;
            s.expect_health(P2, HERO_HEALTH - on_hero);
            s.expect_health(P1, HERO_HEALTH);
        }

        #[test]
        fn r59_a_unit_an_earlier_hit_brought_to_0_is_not_hit_again_and_dies_after_the_last_hit() {
            let mut deaths = 0;
            for seed in 1..=8 {
                let mut s = played(false, json!({ "field": [MR_TOKEN] }), &format!("cosmality-{seed}"));
                let token = s.unit_at(P2, 1).id;
                to_its_awakening(&mut s);

                let hits = hits(&s);
                assert_eq!(hits.len(), 10);
                assert!(hits.iter().filter(|hit| hit.target_id == token).count() <= 1);
                let died = s.events().iter().position(|event| {
                    matches!(event, GameEvent::Destroyed { instance_id, .. } if *instance_id == token)
                });
                if let Some(died) = died {
                    deaths += 1;
                    assert!(died > hits[9].index);
                }
            }
            assert!(deaths > 0);
        }

        #[test]
        fn r346_each_hit_pierces_the_enemy_heros_armor() {
            let mut s = played(false, json!({ "armor": 20 }), "cosmality");
            to_its_awakening(&mut s);

            assert_eq!(hits(&s).len(), 10);
            s.expect_health(P2, HERO_HEALTH - 10);
            assert_eq!(s.state().players.p2.hero.armor, 20);
        }

        #[test]
        fn r1839001_awake_it_is_not_summoning_sick_and_attacks_that_turn() {
            let mut s = played(false, json!({}), "cosmality");
            to_its_awakening(&mut s);
            s.expect_health(P2, HERO_HEALTH - 10);

            s.attack(ID, "hero");
            s.expect_health(P2, HERO_HEALTH - 10 - 10);
        }

        #[test]
        fn r386_its_damage_reads_through_param_an_upgrade_adds_a_hit() {
            let mut s = played(false, json!({}), "cosmality");
            assert_eq!(crate::upgrade_number(&mut s, ID, "damage"), 11);
            to_its_awakening(&mut s);

            assert_eq!(hits(&s).len(), 11);
            s.expect_health(P2, HERO_HEALTH - 11);
        }
    }

    mod radiant {
        use super::*;

        #[test]
        fn r275_a_20_12_whose_awakening_deals_20_hits_of_1() {
            let mut s = played(true, json!({}), "cosmality");
            s.expect_stats(ID, json!({ "attack": 20, "health": 12 }));
            to_its_awakening(&mut s);

            let hits = hits(&s);
            assert_eq!(hits.len(), 20);
            assert!(hits.iter().all(|hit| hit.amount == 1 && hit.target_id == ENEMY_HERO));
            s.expect_health(P2, HERO_HEALTH - 20);
        }
    }
